  static void SubmitWithAttachments(EditCommand baseCommand){if(!attachmentsReady&&!NeedsSummonHistory){Apply(baseCommand);return;}var session=Host.Session;var commands=new List<EditCommand>{baseCommand};var currentMaterials=session.Materials().Where(m=>m.HostId==selected).ToArray();var currentCounters=session.Counters().Where(c=>c.CardId==selected).ToArray();bool xyz=zone==4&&(EffectiveType&0x800000)!=0;bool onField=zone==4&&(EffectiveType&1)!=0;
   if(attachmentsReady&&materialDraft.Count>0&&!xyz)throw new InvalidDataException("请先移除配置的超量素材，或将卡片设为场上的超量怪兽");if(counterDraft.Any(c=>Num(c.Count,65535)>0)&&(!onField||(position&5)==0))throw new InvalidDataException("指示物只能放置在怪兽区表侧表示的怪兽上");
   foreach(var m in currentMaterials)if(attachmentsReady&&!materialDraft.Any(d=>d.Id==m.CardId)){var remove=EditCommand.Create(3);remove.Target=m.CardId;commands.Add(remove);}
   foreach(var group in materialDraft.Where(m=>m.Id==0).GroupBy(m=>new{m.Code,m.Owner})){var add=EditCommand.Create(9);add.Target=selected;add.Code=group.Key.Code;add.Owner=group.Key.Owner;add.Value=(uint)group.Count();commands.Add(add);}
   foreach(uint type in (attachmentsReady?currentCounters:new EditorCounter[0]).Select(c=>c.Type).Union(counterDraft.Select(c=>c.Type))){var draft=counterDraft.FirstOrDefault(c=>c.Type==type);uint next=draft==null?0:Num(draft.Count,65535);var old=currentCounters.FirstOrDefault(c=>c.Type==type);if(next==0&&old.Count==0)continue;var set=EditCommand.Create(10);set.Target=selected;set.Code=type;set.Value=next;commands.Add(set);}
   AppendSummonHistory(commands,baseCommand);ulong createdId=0;Action<EditCommand,EditorCard[],EditorCard[]> track=(edit,before,after)=>{if(selected==0&&edit.Opcode==1&&edit.Code==baseCommand.Code)createdId=after.FirstOrDefault(c=>c.Code==baseCommand.Code&&c.Player==baseCommand.Player&&!before.Any(b=>b.Id==c.Id)).Id;};session.Applied+=track;int result;try{result=session.ApplyGroup(commands);}finally{session.Applied-=track;}if(result!=0)throw new InvalidOperationException("素材／指示物未保存："+new[]{"成功","编辑器未启用","当前时点不可编辑","局面已变化","参数无效","卡片无效","不适用的卡片或数量","位置已占用"}[Math.Min(result,7)]);if(selected==0)selected=createdId;if(selected!=0&&session.Cards().Any(c=>c.Id==selected)){legacyMode=1;ReadAttachments();ReadSummonHistory(selected);}else{selected=0;legacyMode=0;ResetAttachments();ResetSummonHistory();}
